1	import { redirect } from "next/navigation";
2	import type { UserRole } from "@prisma/client";
3	import { auth } from "@/auth";
4	import { prisma } from "@/lib/prisma";
5	
6	export type SessionUser = {
7	  id: string;
8	  email: string;
9	  name: string;
10	  role: UserRole;
11	  image?: string | null;
12	};
13	
14	/** The landing route for each role after login. */
15	export function roleHome(role: UserRole): string {
16	  switch (role) {
17	    case "CREATOR":
18	      return "/creator";
19	    case "AGENCY":
20	      return "/agency";
21	    case "COMPANY":
22	    case "ADMIN":
23	    default:
24	      return "/app";
25	  }
26	}
27	
28	/** Session user or null. Use in API routes (which return 401/404, not redirect). */
29	export async function getSessionUser(): Promise<SessionUser | null> {
30	  const session = await auth();
31	  if (!session?.user) return null;
32	  return session.user as SessionUser;
33	}
34	
35	/** Redirects to /login if unauthenticated. For use in Server Components/pages. */
36	export async function requireAuth(): Promise<SessionUser> {
37	  const user = await getSessionUser();
38	  if (!user) redirect("/login");
39	  return user;
40	}
41	
42	/**
43	 * Enforces role membership (default-deny, OWASP-ACLFUNC-001). Unauthenticated
44	 * users go to /login; authenticated users lacking the role are sent to their
45	 * own home rather than shown a forbidden page.
46	 */
47	export async function requireRole(
48	  role: UserRole | UserRole[],
49	): Promise<SessionUser> {
50	  const user = await requireAuth();
51	  const allowed = Array.isArray(role) ? role : [role];
52	  if (!allowed.includes(user.role)) {
53	    redirect(roleHome(user.role));
54	  }
55	  return user;
56	}
57	
58	/** Company user + their profile, or redirect. */
59	export async function requireCompany() {
60	  const user = await requireRole(["COMPANY", "ADMIN"]);
61	  const company = await prisma.companyProfile.findUnique({
62	    where: { userId: user.id },
63	  });
64	  if (!company) redirect("/onboarding/company");
65	  return { user, company };
66	}
67	
68	/** Creator user + their profile, or redirect. */
69	export async function requireCreator() {
70	  const user = await requireRole(["CREATOR", "ADMIN"]);
71	  const creator = await prisma.creatorProfile.findUnique({
72	    where: { userId: user.id },
73	  });
74	  if (!creator) redirect("/onboarding/creator");
75	  return { user, creator };
76	}
77	
78	/** Agency user + their profile, or redirect. */
79	export async function requireAgency() {
80	  const user = await requireRole(["AGENCY", "ADMIN"]);
81	  const agency = await prisma.agencyProfile.findUnique({
82	    where: { userId: user.id },
83	    include: { clientWorkspaces: true },
84	  });
85	  if (!agency) redirect("/onboarding/agency");
86	  return { user, agency };
87	}
