32	export interface ButtonProps
33	  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
34	    VariantProps<typeof buttonVariants> {}
35	
36	export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
37	  ({ className, variant, size, ...props }, ref) => (
38	    <button
39	      ref={ref}
