"use client";

import { useState, useTransition } from "react";
import { UserPlus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Field } from "@/components/ui/field";
import { VERTICALS } from "@/lib/constants";
import { addManagedCreator } from "@/app/actions/agency";

/** Add a single managed creator to the roster (creator agency). */
export function AddCreatorForm() {
  const [displayName, setDisplayName] = useState("");
  const [headline, setHeadline] = useState("");
  const [followers, setFollowers] = useState("");
  const [pricePerPost, setPricePerPost] = useState("");
  const [selectedVerticals, setSelectedVerticals] = useState<string[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isPending, startTransition] = useTransition();

  function toggleVertical(vertical: string) {
    setSelectedVerticals((current) =>
      current.includes(vertical)
        ? current.filter((entry) => entry !== vertical)
        : [...current, vertical],
    );
  }

  function toInteger(value: string): number {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? Math.trunc(parsed) : Number.NaN;
  }

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(null);
    startTransition(async () => {
      const result = await addManagedCreator({
        displayName,
        headline,
        followers: toInteger(followers),
        pricePerPost: toInteger(pricePerPost),
        verticals: selectedVerticals,
      });
      if (!result.ok) {
        setError(result.error);
        return;
      }
      setDisplayName("");
      setHeadline("");
      setFollowers("");
      setPricePerPost("");
      setSelectedVerticals([]);
    });
  }

  return (
    <form onSubmit={handleSubmit} className="flex flex-col gap-4">
      <div className="grid gap-4 sm:grid-cols-2">
        <Field label="Creator name" htmlFor="creator-name" required>
          <Input
            id="creator-name"
            value={displayName}
            onChange={(event) => setDisplayName(event.target.value)}
            placeholder="Jordan Rivera"
            maxLength={120}
            required
          />
        </Field>
        <Field label="Headline" htmlFor="creator-headline" required>
          <Input
            id="creator-headline"
            value={headline}
            onChange={(event) => setHeadline(event.target.value)}
            placeholder="B2B SaaS growth advisor"
            maxLength={200}
            required
          />
        </Field>
        <Field label="Followers" htmlFor="creator-followers" required>
          <Input
            id="creator-followers"
            type="number"
            inputMode="numeric"
            min={0}
            step={100}
            value={followers}
            onChange={(event) => setFollowers(event.target.value)}
            placeholder="12000"
            required
          />
        </Field>
        <Field label="Price per post (€)" htmlFor="creator-price" required hint="Whole euros">
          <Input
            id="creator-price"
            type="number"
            inputMode="numeric"
            min={0}
            step={10}
            value={pricePerPost}
            onChange={(event) => setPricePerPost(event.target.value)}
            placeholder="450"
            required
          />
        </Field>
      </div>

      <Field label="Verticals" hint="Optional — pick the niches this creator covers">
        <div className="flex flex-wrap gap-2">
          {VERTICALS.map((vertical) => {
            const isSelected = selectedVerticals.includes(vertical);
            return (
              <button
                key={vertical}
                type="button"
                aria-pressed={isSelected}
                onClick={() => toggleVertical(vertical)}
                className={
                  isSelected
                    ? "rounded-full border border-brand bg-brand/10 px-3 py-1 text-xs font-medium text-brand-700"
                    : "rounded-full border border-border bg-white px-3 py-1 text-xs font-medium text-muted-foreground hover:bg-muted"
                }
              >
                {vertical}
              </button>
            );
          })}
        </div>
      </Field>

      {error && <p className="text-sm text-danger">{error}</p>}
      <div>
        <Button type="submit" disabled={isPending}>
          <UserPlus className="size-4" />
          {isPending ? "Adding…" : "Add creator"}
        </Button>
      </div>
    </form>
  );
}

"use client";

import { useState, useTransition } from "react";
import { Upload } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Field } from "@/components/ui/field";
import { importRosterCsv } from "@/app/actions/agency";

const CSV_PLACEHOLDER = `name,headline,followers,pricePerPost,verticals
Jordan Rivera,B2B SaaS growth advisor,12000,450,B2B SaaS|DevTools
Priya Nair,Fintech operator & angel,8400,320,Fintech`;

type Summary = { tone: "ok" | "error"; text: string };

/** Bulk import managed creators by pasting CSV rows (creator agency). */
export function CsvImportForm() {
  const [csv, setCsv] = useState("");
  const [summary, setSummary] = useState<Summary | null>(null);
  const [isPending, startTransition] = useTransition();

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSummary(null);
    startTransition(async () => {
      const result = await importRosterCsv(csv);
      if (!result.ok) {
        setSummary({ tone: "error", text: result.error });
        return;
      }
      setSummary({ tone: "ok", text: result.message });
      setCsv("");
    });
  }

  return (
    <form onSubmit={handleSubmit} className="flex flex-col gap-4">
      <Field
        label="Paste CSV"
        htmlFor="roster-csv"
        hint="Headers: name, headline, followers, pricePerPost, verticals. Separate verticals with | or ;. Up to 200 rows; invalid rows are skipped."
      >
        <Textarea
          id="roster-csv"
          value={csv}
          onChange={(event) => setCsv(event.target.value)}
          placeholder={CSV_PLACEHOLDER}
          rows={7}
          className="font-mono text-xs"
          spellCheck={false}
        />
      </Field>
      {summary && (
        <p className={summary.tone === "ok" ? "text-sm text-success" : "text-sm text-danger"}>
          {summary.text}
        </p>
      )}
      <div>
        <Button type="submit" variant="outline" disabled={isPending}>
          <Upload className="size-4" />
          {isPending ? "Importing…" : "Import roster"}
        </Button>
      </div>
    </form>
  );
}

"use client";

import { useState, useTransition } from "react";
import { Check } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { updateManagedCreator } from "@/app/actions/agency";

/** Inline edit of a managed creator's rate + availability. */
export function EditRateForm({
  creatorId,
  currentPrice,
  currentAvailable,
}: {
  creatorId: string;
  currentPrice: number;
  currentAvailable: boolean;
}) {
  const [price, setPrice] = useState(String(currentPrice));
  const [available, setAvailable] = useState(currentAvailable);
  const [status, setStatus] = useState<{ tone: "ok" | "error"; text: string } | null>(null);
  const [isPending, startTransition] = useTransition();

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setStatus(null);
    const priceValue = Number(price);
    startTransition(async () => {
      const result = await updateManagedCreator(creatorId, {
        pricePerPost: Number.isFinite(priceValue) ? Math.trunc(priceValue) : Number.NaN,
        available,
      });
      setStatus(
        result.ok
          ? { tone: "ok", text: "Saved" }
          : { tone: "error", text: result.error },
      );
    });
  }

  return (
    <form onSubmit={handleSubmit} className="flex flex-wrap items-center gap-2">
      <div className="relative">
        <span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-sm text-muted-foreground">
          €
        </span>
        <label htmlFor={`rate-${creatorId}`} className="sr-only">
          Price per post in euros
        </label>
        <Input
          id={`rate-${creatorId}`}
          type="number"
          inputMode="numeric"
          min={0}
          step={10}
          value={price}
          onChange={(event) => setPrice(event.target.value)}
          className="h-9 w-28 pl-6 text-sm"
        />
      </div>
      <label className="inline-flex items-center gap-1.5 text-xs text-muted-foreground">
        <input
          type="checkbox"
          checked={available}
          onChange={(event) => setAvailable(event.target.checked)}
          className="size-4 rounded border-border accent-brand"
        />
        Available
      </label>
      <Button type="submit" size="sm" variant="outline" disabled={isPending}>
        <Check className="size-4" />
        {isPending ? "Saving…" : "Save"}
      </Button>
      {status && (
        <span
          className={
            status.tone === "ok" ? "text-xs text-success" : "text-xs text-danger"
          }
        >
          {status.text}
        </span>
      )}
    </form>
  );
}

import Link from "next/link";
